let data = msg.payload;

// Function to reduce >100 values repeatedly and round to 2 decimals
function processValue(val) {
    let num = parseFloat(val);
    while (num > 100) {
        num = num / 10;
    }
    return parseFloat(num.toFixed(2));
}

// Create the new output object
let processedData = {
    field1: processValue(data.field1),
    field2: processValue(data.field2),
    field3: processValue(data.field3),
    field4: processValue(data.field4),
    field5: processValue(data.field5),
    field6: processValue(data.field6),
    field7: processValue(data.field7),
    field8: processValue(data.field8)
};

msg.payload = processedData;
return msg;
